import java.util.Scanner;

public class Personenzahl {

 public static void main(String[] args) {
 Scanner keyScan = new Scanner(System.in);
 System.out.print("Raumgrösse: ");
 int raumgroesse = keyScan.nextInt();
 System.out.print("Personen: ");
 int personen = keyScan.nextInt();

 int maxPersonen = raumgroesse / 4;
 if (personen > maxPersonen) {
 System.out.println("Limite überschritten");
 } else if (personen == maxPersonen) {
 System.out.println("Limite erreicht");
 } else {
 System.out.println("Es hat noch Platz");
 }

 keyScan.close();
 }
}

public boolean ueberschreitung(double grenzwert) {
 if (tage < 7) {
 return false;
 }
 double sum = 0;
 for (int i = tage - 7; i < tage; i++) {
 sum += fallzahlen[i];
 }
 double average = sum / 7;
 return average > grenzwert;
}

