import java.util.HashMap;

public class Anlass {
 private HashMap<String, Besucher> besucher = new HashMap<>();

 public void addBesucher(String id, String name, int timeIn) {
 Besucher b = new Besucher(name, timeIn);
 besucher.put(id, b);
 }

 public boolean setTimeOut(String id, int timeOut) {
 Besucher b = besucher.get(id);
 if (b != null) {
 b.setTimeOut(timeOut);
 return true;
 }
 return false;
 }

 public void traceContact(String id) {
 Besucher infiziert = besucher.get(id);
 if (infiziert != null) {
 int infiziertTimeIn = infiziert.getTimeIn();
 int infiziertTimeOut = infiziert.getTimeOut();
 for (String key : besucher.keySet()) {
 Besucher b = besucher.get(key);
 if (b != null && (b.getTimeIn() <= infiziertTimeOut && b.getTimeOut() >= infiziertTimeIn)) {
 System.out.println("ID: " + key + ", Name: " + b.getName());
 }
 }
 }
 }
}
